content.solution_code:
class MagicOrb {
  #energy = 0;

  constructor() {
    // Initializing #energy directly as a class field.
  }

  charge(amount) {
    if (amount > 0) {
      this.#energy += amount;
    }
  }

  drain(amount) {
    if (amount > 0) {
      this.#energy = Math.max(0, this.#energy - amount);
    }
  }

  getEnergyLevel() {
    return this.#energy;
  }
}

// Example Usage:
const orb = new MagicOrb();
console.log(`Initial energy: ${orb.getEnergyLevel()}`); // 0
orb.charge(25);
console.log(`After charging 25: ${orb.getEnergyLevel()}`); // 25
orb.drain(10);
console.log(`After draining 10: ${orb.getEnergyLevel()}`); // 15
orb.drain(20);
console.log(`After draining 20 (should be 0): ${orb.getEnergyLevel()}`); // 0
orb.charge(-5);
console.log(`After charging -5 (should ignore): ${orb.getEnergyLevel()}`); // 0

